import re

def parse_duration(s: str) -> int:
    if not isinstance(s, str) or not s.strip():
        raise ValueError("Empty or invalid duration string")

    tokens = re.findall(r'(\d+)([hms])', s)
    if not tokens:
        raise ValueError("Empty or invalid duration string")

    seen = set()
    total = 0
    for num, unit in tokens:
        if unit in seen:
            raise ValueError(f"Duplicate unit '{unit}'")
        seen.add(unit)
        if unit == 'h':
            total += int(num) * 3600
        elif unit == 'm':
            total += int(num) * 60
        else:
            total += int(num)

    if re.sub(r'\d+[hms]', '', s):
        raise ValueError("Empty or invalid duration string")

    return total
