import math

def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    units = [('bi', 10 ** 9), ('mi', 10 ** 6), ('mil', 10 ** 3)]
    for name, factor in units:
        value = n / factor
        rounded = math.floor(value * 10 + 0.5) / 10
        if 1 <= rounded < 1000:
            if rounded % 1 == 0:
                return f"{int(rounded)} {name}"
            return f"{rounded:.1f}".replace('.', ',') + ' ' + name
    return str(n)
