def wrap(text: str, width: int) -> list[str]:
    if width <= 0:
        return []
    pieces = []
    for word in text.split():
        if len(word) > width:
            pieces.extend(word[i:i + width] for i in range(0, len(word), width))
        else:
            pieces.append(word)
    lines = []
    current = ""
    for piece in pieces:
        if not current:
            current = piece
        elif len(current) + 1 + len(piece) <= width:
            current += " " + piece
        else:
            lines.append(current)
            current = piece
    if current:
        lines.append(current)
    return lines
