def deep_merge(base: dict, override: dict) -> dict:
    def _copy(value):
        if isinstance(value, dict):
            return {k: _copy(v) for k, v in value.items()}
        if isinstance(value, list):
            return [_copy(v) for v in value]
        return value

    result = {}
    keys = list(base.keys()) + [k for k in override.keys() if k not in base]
    for key in keys:
        if key not in override:
            result[key] = _copy(base.get(key))
        elif override[key] is None:
            continue
        else:
            base_val = base.get(key)
            if isinstance(base_val, dict) and isinstance(override[key], dict):
                result[key] = deep_merge(base_val, override[key])
            else:
                result[key] = _copy(override[key])
    return result
