import ipaddress


def ip_allowed(ip: str, networks: list[str]) -> bool:
    # Parse the address; an invalid address returns False.
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return False

    # An IPv4-mapped IPv6 address (e.g. ::ffff:10.0.0.5) is treated as the
    # IPv4 address it carries.
    if addr.is_ipv4_mapped:
        addr = addr.ipv4_mapped

    # Parse networks; an invalid network raises ValueError. Host bits may be set.
    try:
        parsed_networks = [ipaddress.ip_network(net, strict=False) for net in networks]
    except ValueError:
        raise

    # Compare only against networks of the same family.
    for net in parsed_networks:
        if addr.version != net.version:
            continue
        if addr in net:
            return True

    return False
