import ipaddress


def ip_allowed(ip: str, networks: list[str]) -> bool:
    try:
        addr = ipaddress.ip_address(ip)
    except ValueError:
        return False

    def normalize(x):
        if x.version == 6 and x.is_ipv4_mapped:
            return ipaddress.IPv4Address(x.packed[-4:])
        return x

    for net in networks:
        try:
            network = ipaddress.ip_network(net, strict=False)
        except ValueError:
            raise ValueError(f"Invalid network: {net!r}")

        addr = normalize(addr)
        network = normalize(network)

        if addr.version != network.version:
            continue

        if addr in network:
            return True

    return False
