def parse_duration(s: str) -> int:
    if not s:
        raise ValueError("Empty duration string")
    total = 0
    i = 0
    n = len(s)
    while i < n:
        start = i
        while i < n and s[i].isdigit():
            i += 1
        if i == start:
            raise ValueError(f"Invalid duration string: {s!r}")
        number = int(s[start:i])
        if i < n and s[i] in 'hms':
            unit = s[i]
            i += 1
        else:
            raise ValueError(f"Invalid duration string: {s!r}")
        if unit == 'h':
            total += number * 3600
        elif unit == 'm':
            total += number * 60
        else:
            total += number
    return total
