from decimal import Decimal, ROUND_HALF_UP

def compact(n: int) -> str:
    if n < 1000:
        return str(n)

    units = [(10**3, 'mil'), (10**6, 'mi'), (10**9, 'bi')]

    if n < 10**6:
        unit_idx = 0
    elif n < 10**9:
        unit_idx = 1
    else:
        unit_idx = 2

    scale = units[unit_idx][0]
    name = units[unit_idx][1]

    value = (Decimal(n) / Decimal(scale)).quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)

    while value >= 1000 and unit_idx < len(units) - 1:
        unit_idx += 1
        scale = units[unit_idx][0]
        name = units[unit_idx][1]
        value = (Decimal(n) / Decimal(scale)).quantize(Decimal('0.1'), rounding=ROUND_HALF_UP)

    s = format(value, 'f').replace('.', ',', 1)
    if s.endswith(',0'):
        s = s[:-2]

    return f'{s} {name}'
