def compare_versions(a: str, b: str) -> int:
    def parse(v: str):
        core, _, _ = v.partition('+')        # build metadata is ignored
        core, _, pre = core.partition('-')   # split off prerelease
        major, minor, patch = core.split('.')
        return int(major), int(minor), int(patch), pre

    am, an, ap, apre = parse(a)
    bm, bn, bp, bpre = parse(b)

    for x, y in ((am, bm), (an, bn), (ap, bp)):
        if x != y:
            return -1 if x < y else 1

    a_ids = apre.split('.') if apre else []
    b_ids = bpre.split('.') if bpre else []

    if not a_ids and not b_ids:
        return 0
    if not a_ids:
        return 1
    if not b_ids:
        return -1

    for i in range(min(len(a_ids), len(b_ids))):
        ai, bi = a_ids[i], b_ids[i]
        an, bn = ai.isascii() and ai.isdigit(), bi.isascii() and bi.isdigit()
        if an and bn:
            if int(ai) != int(bi):
                return -1 if int(ai) < int(bi) else 1
        elif an != bn:
            return -1 if an else 1
        elif ai != bi:
            return -1 if ai < bi else 1

    return -1 if len(a_ids) < len(b_ids) else 1
