def natural_sorted(names: list[str]) -> list[str]:
    """Sort names with natural ordering: digit runs compare numerically,
    letters compare case-insensitively, and equal names keep input order."""
    DIGITS = '0123456789'

    def key(s: str):
        tokens = []
        i, n = 0, len(s)
        while i < n:
            j = i
            while j < n and s[j] in DIGITS:
                j += 1
            if j > i:
                tokens.append((1, int(s[i:j])))
            else:
                j = i
                while j < n and s[j] not in DIGITS:
                    j += 1
                tokens.append((0, s[i:j].lower()))
            i = j
        return tuple(tokens)

    return sorted(names, key=key)
