def wrap(text: str, width: int) -> list[str]:
    words = text.split()
    if not words:
        return []

    lines = []
    current_line = []
    current_width = 0

    for word in words:
        pieces = [word[i:i + width] for i in range(0, len(word), width)]

        if current_line and current_width + 1 + len(pieces[0]) <= width:
            current_line.append(pieces[0])
            current_width += 1 + len(pieces[0])
        else:
            current_line = [pieces[0]]
            current_width = len(pieces[0])

        for piece in pieces[1:]:
            if current_width + 1 + len(piece) <= width:
                current_line.append(piece)
                current_width += 1 + len(piece)
            else:
                current_line = [piece]
                current_width = len(piece)

    lines.append(" ".join(current_line))
    return lines
