            continue
        stripped = line.strip()
        if stripped == '':
            continue
        if stripped.startswith('[') and stripped.endswith(']'):
            current_section = stripped[1:-1].strip()
            continue
        if '=' in line:
            idx = line.index('=')
            k = line[:idx].strip()
            if k == key and current_section == section:
                lines[i] = f"{key} = {value}"
                found = True
    if not found:
        raise KeyError(f"Key '{key}' not found in section '{section}'")
    return '\n'.join(lines)
