from datetime import datetime, timezone


def latest_by_key(records: list[dict], key: str) -> list[dict]:
    def _parse(dt_str: str) -> datetime:
        s = dt_str.strip()
        if s.endswith('Z'):
            s = s[:-1] + '+00:00'
        dt = datetime.fromisoformat(s)
        if dt.tzinfo is None:
            dt = dt.replace(tzinfo=timezone.utc)
        return dt.astimezone(timezone.utc)

    best: dict[str, tuple[datetime, dict]] = {}
    order: list[str] = []

    for record in records:
        value = record[key]
        dt = _parse(record['updated_at'])
        if value not in best:
            best[value] = (dt, record)
            order.append(value)
        elif dt >= best[value][0]:
            best[value] = (dt, record)

    return [best[value][1] for value in order]
